-- Outbound runner registration and short-lived job leases.
--
-- Account-authenticated clients may register local runners and enqueue work,
-- but runner activation, heartbeats, and job leases cross a separate
-- service-role Edge Function. Pairing, session, and lease secrets are always
-- generated by clients; only SHA-256 hashes are stored in Postgres.

create function public.qorpera_runner_capabilities_valid(p_capabilities jsonb)
returns boolean
language sql
immutable
set search_path = ''
as $$
	select jsonb_typeof(p_capabilities) = 'array'
		and jsonb_array_length(p_capabilities) between 1 and 8
		and not exists (
			select 1
			from jsonb_array_elements(p_capabilities) as capability(value)
			where jsonb_typeof(capability.value) <> 'string'
				or (capability.value #>> '{}') not in ('agent_turn', 'git_worktree', 'company_substrate')
		)
		and (
			select count(*) = count(distinct capability.value)
			from jsonb_array_elements_text(p_capabilities) as capability(value)
		)
$$;

create table public.qorpera_runners (
	id uuid primary key default extensions.gen_random_uuid(),
	profile_id uuid not null references public.qorpera_profiles(id) on delete cascade,
	client_runner_id uuid not null,
	display_name text not null check (char_length(btrim(display_name)) between 1 and 120),
	runner_kind text not null default 'local' check (runner_kind in ('local', 'qorpera_computer')),
	capabilities jsonb not null check (public.qorpera_runner_capabilities_valid(capabilities)),
	max_concurrency integer not null default 1 check (max_concurrency between 1 and 16),
	status text not null default 'pending' check (status in ('pending', 'active', 'revoked')),
	platform text check (
		platform is null or (
			char_length(platform) between 1 and 80
			and platform ~ '^[a-z0-9][a-z0-9._-]*$'
		)
	),
	runner_version text check (runner_version is null or char_length(btrim(runner_version)) between 1 and 80),
	activation_token_sha256 text not null check (activation_token_sha256 ~ '^[0-9a-f]{64}$'),
	activation_expires_at timestamptz not null,
	session_token_sha256 text check (session_token_sha256 is null or session_token_sha256 ~ '^[0-9a-f]{64}$'),
	session_expires_at timestamptz,
	previous_session_token_sha256 text check (
		previous_session_token_sha256 is null or previous_session_token_sha256 ~ '^[0-9a-f]{64}$'
	),
	previous_session_expires_at timestamptz,
	last_renewal_id uuid,
	registered_by_user_id uuid not null references auth.users(id) on delete restrict,
	created_at timestamptz not null default statement_timestamp(),
	activated_at timestamptz,
	last_seen_at timestamptz,
	revoked_by_user_id uuid references auth.users(id) on delete restrict,
	revoked_at timestamptz,
	unique (profile_id, client_runner_id),
	check (activation_expires_at >= created_at + interval '15 minutes'),
	check ((session_token_sha256 is null) = (session_expires_at is null)),
	check ((previous_session_token_sha256 is null) = (previous_session_expires_at is null)),
	check ((revoked_by_user_id is null) = (revoked_at is null)),
	check (
		(status = 'pending' and activated_at is null and session_token_sha256 is null and revoked_at is null)
		or (status = 'active' and activated_at is not null and session_token_sha256 is not null and revoked_at is null)
		or (status = 'revoked' and revoked_at is not null and session_token_sha256 is null)
	)
);

create index qorpera_runners_profile on public.qorpera_runners (profile_id, created_at);
create index qorpera_runners_session_expiry
	on public.qorpera_runners (session_expires_at)
	where status = 'active';

create table public.qorpera_runner_jobs (
	id uuid primary key default extensions.gen_random_uuid(),
	profile_id uuid not null references public.qorpera_profiles(id) on delete cascade,
	environment_id uuid not null references public.qorpera_company_environments(id) on delete restrict,
	session_id uuid references public.qorpera_shared_sessions(id) on delete restrict,
	substrate_version_id uuid not null references public.qorpera_company_substrate_versions(id) on delete restrict,
	client_job_id uuid not null,
	required_capability text not null check (
		required_capability in ('agent_turn', 'git_worktree', 'company_substrate')
	),
	job_type text not null check (
		char_length(job_type) between 1 and 64
		and job_type ~ '^[a-z][a-z0-9_-]*$'
	),
	payload jsonb not null check (jsonb_typeof(payload) = 'object' and pg_column_size(payload) <= 65536),
	status text not null default 'queued'
		check (status in ('queued', 'leased', 'completed', 'failed', 'cancelled')),
	attempt_count integer not null default 0 check (attempt_count between 0 and 1000),
	runner_id uuid references public.qorpera_runners(id) on delete restrict,
	client_lease_id uuid,
	lease_token_sha256 text check (lease_token_sha256 is null or lease_token_sha256 ~ '^[0-9a-f]{64}$'),
	lease_expires_at timestamptz,
	terminal_lease_token_sha256 text check (
		terminal_lease_token_sha256 is null or terminal_lease_token_sha256 ~ '^[0-9a-f]{64}$'
	),
	result jsonb check (result is null or (jsonb_typeof(result) = 'object' and pg_column_size(result) <= 65536)),
	last_error text check (last_error is null or char_length(last_error) between 1 and 1000),
	created_by_user_id uuid not null references auth.users(id) on delete restrict,
	created_at timestamptz not null default statement_timestamp(),
	started_at timestamptz,
	finished_at timestamptz,
	cancelled_by_user_id uuid references auth.users(id) on delete restrict,
	cancelled_at timestamptz,
	unique (profile_id, client_job_id),
	check ((lease_token_sha256 is null) = (lease_expires_at is null)),
	check ((status = 'leased') = (lease_token_sha256 is not null)),
	check ((status = 'completed') = (result is not null)),
	check ((status in ('completed', 'failed')) = (finished_at is not null)),
	check ((status = 'cancelled') = (cancelled_at is not null)),
	check ((cancelled_by_user_id is null) = (cancelled_at is null))
);

create unique index qorpera_runner_jobs_client_lease
	on public.qorpera_runner_jobs (runner_id, client_lease_id)
	where runner_id is not null and client_lease_id is not null;

create index qorpera_runner_jobs_queue
	on public.qorpera_runner_jobs (profile_id, required_capability, created_at)
	where status in ('queued', 'leased');

create table public.qorpera_runner_audit_receipts (
	id bigint generated always as identity primary key,
	profile_id uuid not null references public.qorpera_profiles(id) on delete cascade,
	runner_id uuid references public.qorpera_runners(id) on delete cascade,
	job_id uuid references public.qorpera_runner_jobs(id) on delete cascade,
	event_type text not null check (event_type in (
		'runner_registered', 'runner_activated', 'runner_revoked',
		'job_queued', 'job_leased', 'job_lease_renewed', 'job_requeued',
		'job_completed', 'job_failed', 'job_cancelled'
	)),
	payload jsonb not null check (jsonb_typeof(payload) = 'object' and pg_column_size(payload) <= 8192),
	actor_user_id uuid references auth.users(id) on delete restrict,
	created_at timestamptz not null default statement_timestamp()
);

create index qorpera_runner_audit_profile_sequence
	on public.qorpera_runner_audit_receipts (profile_id, id);

alter table public.qorpera_runners enable row level security;
alter table public.qorpera_runner_jobs enable row level security;
alter table public.qorpera_runner_audit_receipts enable row level security;

revoke all on public.qorpera_runners from anon, authenticated;
revoke all on public.qorpera_runner_jobs from anon, authenticated;
revoke all on public.qorpera_runner_audit_receipts from anon, authenticated;

create function public.qorpera_runner_json(p_runner public.qorpera_runners)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
	select jsonb_build_object(
		'runner_id', p_runner.id,
		'profile_id', p_runner.profile_id,
		'client_runner_id', p_runner.client_runner_id,
		'display_name', p_runner.display_name,
		'runner_kind', p_runner.runner_kind,
		'capabilities', p_runner.capabilities,
		'max_concurrency', p_runner.max_concurrency,
		'status', p_runner.status,
		'online', p_runner.status = 'active' and p_runner.session_expires_at > statement_timestamp(),
		'platform', p_runner.platform,
		'runner_version', p_runner.runner_version,
		'activation_expires_at', p_runner.activation_expires_at,
		'session_expires_at', p_runner.session_expires_at,
		'registered_by_user_id', p_runner.registered_by_user_id,
		'created_at', p_runner.created_at,
		'activated_at', p_runner.activated_at,
		'last_seen_at', p_runner.last_seen_at,
		'revoked_by_user_id', p_runner.revoked_by_user_id,
		'revoked_at', p_runner.revoked_at,
		'active_lease_count', (
			select count(*)
			from public.qorpera_runner_jobs as job
			where job.runner_id = p_runner.id and job.status = 'leased'
				and job.lease_expires_at > statement_timestamp()
		)
	)
$$;

create function public.qorpera_runner_job_json(p_job public.qorpera_runner_jobs)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
	select jsonb_build_object(
		'job_id', p_job.id,
		'profile_id', p_job.profile_id,
		'environment_id', p_job.environment_id,
		'session_id', p_job.session_id,
		'substrate_version_id', p_job.substrate_version_id,
		'client_job_id', p_job.client_job_id,
		'required_capability', p_job.required_capability,
		'job_type', p_job.job_type,
		'payload', p_job.payload,
		'status', p_job.status,
		'attempt_count', p_job.attempt_count,
		'runner_id', p_job.runner_id,
		'result', p_job.result,
		'last_error', p_job.last_error,
		'created_by_user_id', p_job.created_by_user_id,
		'created_at', p_job.created_at,
		'started_at', p_job.started_at,
		'lease_expires_at', p_job.lease_expires_at,
		'finished_at', p_job.finished_at,
		'cancelled_by_user_id', p_job.cancelled_by_user_id,
		'cancelled_at', p_job.cancelled_at
	)
$$;

create function public.qorpera_append_runner_audit(
	p_profile_id uuid,
	p_runner_id uuid,
	p_job_id uuid,
	p_event_type text,
	p_payload jsonb,
	p_actor_user_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
	insert into public.qorpera_runner_audit_receipts (
		profile_id, runner_id, job_id, event_type, payload, actor_user_id
	)
	values (p_profile_id, p_runner_id, p_job_id, p_event_type, p_payload, p_actor_user_id);
end
$$;

create function public.qorpera_runner_session_valid(p_runner_id uuid, p_token_sha256 text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
	select exists (
		select 1
		from public.qorpera_runners as runner
		where runner.id = p_runner_id and runner.status = 'active'
			and (
				(runner.session_token_sha256 = p_token_sha256
					and runner.session_expires_at > statement_timestamp())
				or (runner.previous_session_token_sha256 = p_token_sha256
					and runner.previous_session_expires_at > statement_timestamp())
			)
	)
$$;

revoke all on function public.qorpera_runner_capabilities_valid(jsonb) from public;
revoke all on function public.qorpera_runner_json(public.qorpera_runners) from public;
revoke all on function public.qorpera_runner_job_json(public.qorpera_runner_jobs) from public;
revoke all on function public.qorpera_append_runner_audit(uuid, uuid, uuid, text, jsonb, uuid) from public;
revoke all on function public.qorpera_runner_session_valid(uuid, text) from public;

create function public.qorpera_create_runner_registration(
	p_profile_id uuid,
	p_client_runner_id uuid,
	p_display_name text,
	p_capabilities jsonb,
	p_max_concurrency integer,
	p_activation_token_sha256 text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
	v_user_id uuid := auth.uid();
	v_runner public.qorpera_runners%rowtype;
	v_name text := btrim(p_display_name);
begin
	if v_user_id is null or not public.qorpera_can_authorize_profile(p_profile_id) then
		raise exception 'runner registration requires full access' using errcode = '42501';
	end if;
	if p_client_runner_id is null or char_length(v_name) not between 1 and 120
		or not public.qorpera_runner_capabilities_valid(p_capabilities)
		or p_max_concurrency not between 1 and 16
		or p_activation_token_sha256 !~ '^[0-9a-f]{64}$' then
		raise exception 'runner registration is invalid' using errcode = '22023';
	end if;

	select runner.* into v_runner
	from public.qorpera_runners as runner
	where runner.profile_id = p_profile_id and runner.client_runner_id = p_client_runner_id;
	if found then
		if v_runner.display_name <> v_name or v_runner.capabilities <> p_capabilities
			or v_runner.max_concurrency <> p_max_concurrency
			or v_runner.activation_token_sha256 <> p_activation_token_sha256 then
			raise exception 'runner client id is already bound to another registration' using errcode = '23505';
		end if;
		return public.qorpera_runner_json(v_runner);
	end if;

	insert into public.qorpera_runners (
		profile_id, client_runner_id, display_name, capabilities,
		max_concurrency, activation_token_sha256, activation_expires_at,
		registered_by_user_id
	)
	values (
		p_profile_id, p_client_runner_id, v_name, p_capabilities,
		p_max_concurrency, p_activation_token_sha256,
		statement_timestamp() + interval '15 minutes', v_user_id
	)
	returning * into v_runner;
	perform public.qorpera_append_runner_audit(
		v_runner.profile_id, v_runner.id, null, 'runner_registered',
		jsonb_build_object(
			'runner_kind', v_runner.runner_kind,
			'capabilities', v_runner.capabilities,
			'max_concurrency', v_runner.max_concurrency,
			'activation_expires_at', v_runner.activation_expires_at
		), v_user_id
	);
	return public.qorpera_runner_json(v_runner);
end
$$;

create function public.qorpera_reissue_runner_activation(
	p_runner_id uuid,
	p_activation_token_sha256 text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
	v_runner public.qorpera_runners%rowtype;
begin
	select runner.* into v_runner from public.qorpera_runners as runner
	where runner.id = p_runner_id for update;
	if auth.uid() is null or not found or not public.qorpera_can_authorize_profile(v_runner.profile_id) then
		raise exception 'runner registration requires full access' using errcode = '42501';
	end if;
	if v_runner.status <> 'pending' or p_activation_token_sha256 !~ '^[0-9a-f]{64}$' then
		raise exception 'runner activation cannot be reissued' using errcode = '55000';
	end if;
	update public.qorpera_runners
	set activation_token_sha256 = p_activation_token_sha256,
		activation_expires_at = statement_timestamp() + interval '15 minutes'
	where id = p_runner_id returning * into v_runner;
	return public.qorpera_runner_json(v_runner);
end
$$;

create function public.qorpera_list_runners(p_profile_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
	if auth.uid() is null or public.qorpera_member_role(p_profile_id) is null then
		raise exception 'runner list requires profile access' using errcode = '42501';
	end if;
	return coalesce((
		select jsonb_agg(public.qorpera_runner_json(runner) order by runner.created_at, runner.id)
		from public.qorpera_runners as runner where runner.profile_id = p_profile_id
	), '[]'::jsonb);
end
$$;

create function public.qorpera_revoke_runner(p_runner_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
	v_user_id uuid := auth.uid();
	v_runner public.qorpera_runners%rowtype;
	v_job public.qorpera_runner_jobs%rowtype;
begin
	select runner.* into v_runner from public.qorpera_runners as runner
	where runner.id = p_runner_id for update;
	if v_user_id is null or not found or not public.qorpera_can_authorize_profile(v_runner.profile_id) then
		raise exception 'runner revocation requires full access' using errcode = '42501';
	end if;
	if v_runner.status = 'revoked' then return public.qorpera_runner_json(v_runner); end if;

	for v_job in
		select job.* from public.qorpera_runner_jobs as job
		where job.runner_id = p_runner_id and job.status = 'leased' for update
	loop
		if v_job.attempt_count >= 8 then
			update public.qorpera_runner_jobs
			set status = 'failed', terminal_lease_token_sha256 = lease_token_sha256,
				lease_token_sha256 = null, lease_expires_at = null,
				finished_at = statement_timestamp(), last_error = 'Runner was revoked after the final lease attempt'
			where id = v_job.id returning * into v_job;
			perform public.qorpera_append_runner_audit(
				v_job.profile_id, p_runner_id, v_job.id, 'job_failed',
				jsonb_build_object('attempt_count', v_job.attempt_count, 'reason', 'runner_revoked'), v_user_id
			);
		else
			update public.qorpera_runner_jobs
			set status = 'queued', runner_id = null, client_lease_id = null,
				lease_token_sha256 = null, lease_expires_at = null,
				last_error = 'Runner was revoked before completion'
			where id = v_job.id returning * into v_job;
			perform public.qorpera_append_runner_audit(
				v_job.profile_id, p_runner_id, v_job.id, 'job_requeued',
				jsonb_build_object('attempt_count', v_job.attempt_count, 'reason', 'runner_revoked'), v_user_id
			);
		end if;
	end loop;

	update public.qorpera_runners
	set status = 'revoked', session_token_sha256 = null, session_expires_at = null,
		previous_session_token_sha256 = null, previous_session_expires_at = null,
		last_renewal_id = null, revoked_by_user_id = v_user_id,
		revoked_at = statement_timestamp()
	where id = p_runner_id returning * into v_runner;
	perform public.qorpera_append_runner_audit(
		v_runner.profile_id, v_runner.id, null, 'runner_revoked', '{}'::jsonb, v_user_id
	);
	return public.qorpera_runner_json(v_runner);
end
$$;

create function public.qorpera_enqueue_runner_job(
	p_environment_id uuid,
	p_session_id uuid,
	p_substrate_version_id uuid,
	p_client_job_id uuid,
	p_required_capability text,
	p_job_type text,
	p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
	v_user_id uuid := auth.uid();
	v_profile_id uuid;
	v_existing public.qorpera_runner_jobs%rowtype;
	v_job public.qorpera_runner_jobs%rowtype;
	v_type text := lower(btrim(p_job_type));
begin
	select environment.profile_id into v_profile_id
	from public.qorpera_company_environments as environment where environment.id = p_environment_id;
	if v_user_id is null or not found or not public.qorpera_can_write_profile(v_profile_id) then
		raise exception 'runner job creation requires write access' using errcode = '42501';
	end if;
	if p_client_job_id is null
		or p_required_capability not in ('agent_turn', 'git_worktree', 'company_substrate')
		or char_length(v_type) not between 1 and 64 or v_type !~ '^[a-z][a-z0-9_-]*$'
		or jsonb_typeof(p_payload) <> 'object' or pg_column_size(p_payload) > 65536
		or not exists (
			select 1 from public.qorpera_company_substrate_versions as version
			where version.id = p_substrate_version_id and version.profile_id = v_profile_id
				and version.environment_id = p_environment_id
		)
		or (p_session_id is not null and not exists (
			select 1 from public.qorpera_shared_sessions as session
			where session.id = p_session_id and session.profile_id = v_profile_id
				and session.environment_id = p_environment_id
		)) then
		raise exception 'runner job is invalid' using errcode = '22023';
	end if;

	select job.* into v_existing from public.qorpera_runner_jobs as job
	where job.profile_id = v_profile_id and job.client_job_id = p_client_job_id;
	if found then
		if v_existing.environment_id <> p_environment_id
			or v_existing.session_id is distinct from p_session_id
			or v_existing.substrate_version_id <> p_substrate_version_id
			or v_existing.required_capability <> p_required_capability
			or v_existing.job_type <> v_type or v_existing.payload <> p_payload then
			raise exception 'runner client job id is already bound to other work' using errcode = '23505';
		end if;
		return public.qorpera_runner_job_json(v_existing);
	end if;

	insert into public.qorpera_runner_jobs (
		profile_id, environment_id, session_id, substrate_version_id,
		client_job_id, required_capability, job_type, payload, created_by_user_id
	)
	values (
		v_profile_id, p_environment_id, p_session_id, p_substrate_version_id,
		p_client_job_id, p_required_capability, v_type, p_payload, v_user_id
	)
	returning * into v_job;
	perform public.qorpera_append_runner_audit(
		v_job.profile_id, null, v_job.id, 'job_queued',
		jsonb_build_object(
			'required_capability', v_job.required_capability,
			'job_type', v_job.job_type
		), v_user_id
	);
	return public.qorpera_runner_job_json(v_job);
end
$$;

create function public.qorpera_list_runner_jobs(p_profile_id uuid, p_limit integer default 200)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
	if auth.uid() is null or public.qorpera_member_role(p_profile_id) is null then
		raise exception 'runner job list requires profile access' using errcode = '42501';
	end if;
	if p_limit not between 1 and 500 then
		raise exception 'runner job page is invalid' using errcode = '22023';
	end if;
	return coalesce((
		select jsonb_agg(public.qorpera_runner_job_json(job) order by job.created_at desc, job.id desc)
		from (
			select candidate.* from public.qorpera_runner_jobs as candidate
			where candidate.profile_id = p_profile_id
			order by candidate.created_at desc, candidate.id desc limit p_limit
		) as job
	), '[]'::jsonb);
end
$$;

create function public.qorpera_cancel_runner_job(p_job_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
	v_user_id uuid := auth.uid();
	v_job public.qorpera_runner_jobs%rowtype;
begin
	select job.* into v_job from public.qorpera_runner_jobs as job
	where job.id = p_job_id for update;
	if v_user_id is null or not found or not (
		v_job.created_by_user_id = v_user_id or public.qorpera_can_authorize_profile(v_job.profile_id)
	) then
		raise exception 'runner job cancellation is not allowed' using errcode = '42501';
	end if;
	if v_job.status = 'cancelled' then return public.qorpera_runner_job_json(v_job); end if;
	if v_job.status in ('completed', 'failed') then
		raise exception 'runner job is already finished' using errcode = '55000';
	end if;
	update public.qorpera_runner_jobs
	set status = 'cancelled', runner_id = null, client_lease_id = null,
		lease_token_sha256 = null, lease_expires_at = null,
		cancelled_by_user_id = v_user_id, cancelled_at = statement_timestamp()
	where id = p_job_id returning * into v_job;
	perform public.qorpera_append_runner_audit(
		v_job.profile_id, null, v_job.id, 'job_cancelled', '{}'::jsonb, v_user_id
	);
	return public.qorpera_runner_job_json(v_job);
end
$$;

create function public.qorpera_list_runner_audit(
	p_profile_id uuid,
	p_after_id bigint default 0,
	p_limit integer default 200
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
	if auth.uid() is null or public.qorpera_member_role(p_profile_id) is null then
		raise exception 'runner audit requires profile access' using errcode = '42501';
	end if;
	if p_after_id < 0 or p_limit not between 1 and 500 then
		raise exception 'runner audit page is invalid' using errcode = '22023';
	end if;
	return coalesce((
		select jsonb_agg(jsonb_build_object(
			'receipt_id', receipt.id,
			'profile_id', receipt.profile_id,
			'runner_id', receipt.runner_id,
			'job_id', receipt.job_id,
			'event_type', receipt.event_type,
			'payload', receipt.payload,
			'actor_user_id', receipt.actor_user_id,
			'created_at', receipt.created_at
		) order by receipt.id)
		from (
			select candidate.* from public.qorpera_runner_audit_receipts as candidate
			where candidate.profile_id = p_profile_id and candidate.id > p_after_id
			order by candidate.id limit p_limit
		) as receipt
	), '[]'::jsonb);
end
$$;

create function public.qorpera_activate_runner(
	p_runner_id uuid,
	p_activation_token_sha256 text,
	p_session_token_sha256 text,
	p_platform text,
	p_runner_version text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
	v_runner public.qorpera_runners%rowtype;
	v_platform text := lower(btrim(p_platform));
	v_version text := btrim(p_runner_version);
begin
	if auth.role() <> 'service_role'
		or p_activation_token_sha256 !~ '^[0-9a-f]{64}$'
		or p_session_token_sha256 !~ '^[0-9a-f]{64}$'
		or p_activation_token_sha256 = p_session_token_sha256
		or char_length(v_platform) not between 1 and 80 or v_platform !~ '^[a-z0-9][a-z0-9._-]*$'
		or char_length(v_version) not between 1 and 80 then
		raise exception 'runner activation is invalid' using errcode = '42501';
	end if;
	select runner.* into v_runner from public.qorpera_runners as runner
	where runner.id = p_runner_id for update;
	if not found then raise exception 'runner activation is unavailable' using errcode = '42501'; end if;
	if v_runner.status = 'active' and v_runner.activation_token_sha256 = p_activation_token_sha256
		and v_runner.session_token_sha256 = p_session_token_sha256 then
		return public.qorpera_runner_json(v_runner);
	end if;
	if v_runner.status <> 'pending' or v_runner.activation_expires_at <= statement_timestamp()
		or v_runner.activation_token_sha256 <> p_activation_token_sha256 then
		raise exception 'runner activation is unavailable' using errcode = '42501';
	end if;
	update public.qorpera_runners
	set status = 'active', platform = v_platform, runner_version = v_version,
		session_token_sha256 = p_session_token_sha256,
		session_expires_at = statement_timestamp() + interval '15 minutes',
		activated_at = statement_timestamp(), last_seen_at = statement_timestamp()
	where id = p_runner_id returning * into v_runner;
	perform public.qorpera_append_runner_audit(
		v_runner.profile_id, v_runner.id, null, 'runner_activated',
		jsonb_build_object('platform', v_runner.platform, 'runner_version', v_runner.runner_version), null
	);
	return public.qorpera_runner_json(v_runner);
end
$$;

create function public.qorpera_heartbeat_runner(
	p_runner_id uuid,
	p_current_token_sha256 text,
	p_next_token_sha256 text,
	p_renewal_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
	v_runner public.qorpera_runners%rowtype;
begin
	if auth.role() <> 'service_role' or p_renewal_id is null
		or p_current_token_sha256 !~ '^[0-9a-f]{64}$'
		or p_next_token_sha256 !~ '^[0-9a-f]{64}$'
		or p_current_token_sha256 = p_next_token_sha256 then
		raise exception 'runner heartbeat is invalid' using errcode = '42501';
	end if;
	select runner.* into v_runner from public.qorpera_runners as runner
	where runner.id = p_runner_id for update;
	if not found or v_runner.status <> 'active' then
		raise exception 'runner session is unavailable' using errcode = '42501';
	end if;
	if v_runner.last_renewal_id = p_renewal_id
		and v_runner.session_token_sha256 = p_next_token_sha256
		and v_runner.previous_session_token_sha256 = p_current_token_sha256
		and v_runner.previous_session_expires_at > statement_timestamp() then
		return public.qorpera_runner_json(v_runner);
	end if;
	if v_runner.session_token_sha256 <> p_current_token_sha256
		or v_runner.session_expires_at <= statement_timestamp() then
		raise exception 'runner session is unavailable' using errcode = '42501';
	end if;
	update public.qorpera_runners
	set previous_session_token_sha256 = session_token_sha256,
		previous_session_expires_at = statement_timestamp() + interval '2 minutes',
		session_token_sha256 = p_next_token_sha256,
		session_expires_at = statement_timestamp() + interval '15 minutes',
		last_renewal_id = p_renewal_id, last_seen_at = statement_timestamp()
	where id = p_runner_id returning * into v_runner;
	return public.qorpera_runner_json(v_runner);
end
$$;

create function public.qorpera_claim_runner_job(
	p_runner_id uuid,
	p_session_token_sha256 text,
	p_client_lease_id uuid,
	p_lease_token_sha256 text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
	v_runner public.qorpera_runners%rowtype;
	v_job public.qorpera_runner_jobs%rowtype;
	v_recovered boolean;
begin
	if auth.role() <> 'service_role' or p_client_lease_id is null
		or p_session_token_sha256 !~ '^[0-9a-f]{64}$'
		or p_lease_token_sha256 !~ '^[0-9a-f]{64}$'
		or not public.qorpera_runner_session_valid(p_runner_id, p_session_token_sha256) then
		raise exception 'runner job claim is invalid' using errcode = '42501';
	end if;
	select runner.* into v_runner from public.qorpera_runners as runner
	where runner.id = p_runner_id and runner.status = 'active' for update;

	select job.* into v_job from public.qorpera_runner_jobs as job
	where job.runner_id = p_runner_id and job.client_lease_id = p_client_lease_id;
	if found then
		if v_job.status <> 'leased' or v_job.lease_expires_at <= statement_timestamp()
			or v_job.lease_token_sha256 <> p_lease_token_sha256 then
			raise exception 'runner lease replay is unavailable' using errcode = '40001';
		end if;
		return public.qorpera_runner_job_json(v_job);
	end if;

	if (
		select count(*) from public.qorpera_runner_jobs as active_job
		where active_job.runner_id = p_runner_id and active_job.status = 'leased'
			and active_job.lease_expires_at > statement_timestamp()
	) >= v_runner.max_concurrency then
		return 'null'::jsonb;
	end if;

	for v_job in
		select exhausted.* from public.qorpera_runner_jobs as exhausted
		where exhausted.profile_id = v_runner.profile_id and exhausted.status = 'leased'
			and exhausted.lease_expires_at <= statement_timestamp()
			and exhausted.attempt_count >= 8 for update skip locked
	loop
		update public.qorpera_runner_jobs
		set status = 'failed', terminal_lease_token_sha256 = lease_token_sha256,
			lease_token_sha256 = null, lease_expires_at = null,
			finished_at = statement_timestamp(), last_error = 'Runner lease expired after the final attempt'
		where id = v_job.id returning * into v_job;
		perform public.qorpera_append_runner_audit(
			v_job.profile_id, v_job.runner_id, v_job.id, 'job_failed',
			jsonb_build_object('attempt_count', v_job.attempt_count, 'reason', 'lease_expired'), null
		);
	end loop;

	select candidate.* into v_job
	from public.qorpera_runner_jobs as candidate
	where candidate.profile_id = v_runner.profile_id
		and candidate.required_capability in (
			select capability.value from jsonb_array_elements_text(v_runner.capabilities) as capability(value)
		)
		and candidate.attempt_count < 8
		and (
			candidate.status = 'queued'
			or (candidate.status = 'leased' and candidate.lease_expires_at <= statement_timestamp())
		)
	order by candidate.created_at, candidate.id
	for update skip locked
	limit 1;
	if not found then return 'null'::jsonb; end if;
	v_recovered := v_job.status = 'leased';

	update public.qorpera_runner_jobs
	set status = 'leased', runner_id = p_runner_id, client_lease_id = p_client_lease_id,
		lease_token_sha256 = p_lease_token_sha256,
		lease_expires_at = statement_timestamp() + interval '2 minutes',
		attempt_count = attempt_count + 1,
		started_at = coalesce(started_at, statement_timestamp()), last_error = null
	where id = v_job.id returning * into v_job;
	perform public.qorpera_append_runner_audit(
		v_job.profile_id, p_runner_id, v_job.id, 'job_leased',
		jsonb_build_object(
			'attempt_count', v_job.attempt_count,
			'lease_expires_at', v_job.lease_expires_at,
			'recovered', coalesce(v_recovered, false)
		), null
	);
	return public.qorpera_runner_job_json(v_job);
end
$$;

create function public.qorpera_renew_runner_job(
	p_runner_id uuid,
	p_session_token_sha256 text,
	p_job_id uuid,
	p_lease_token_sha256 text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
	v_job public.qorpera_runner_jobs%rowtype;
begin
	if auth.role() <> 'service_role'
		or not public.qorpera_runner_session_valid(p_runner_id, p_session_token_sha256) then
		raise exception 'runner job renewal is invalid' using errcode = '42501';
	end if;
	select job.* into v_job from public.qorpera_runner_jobs as job
	where job.id = p_job_id and job.status = 'leased' and job.runner_id = p_runner_id
		and job.lease_token_sha256 = p_lease_token_sha256
		and job.lease_expires_at > statement_timestamp() for update;
	if not found then raise exception 'runner job lease is unavailable' using errcode = '40001'; end if;
	update public.qorpera_runner_jobs
	set lease_expires_at = statement_timestamp() + interval '2 minutes'
	where id = p_job_id returning * into v_job;
	perform public.qorpera_append_runner_audit(
		v_job.profile_id, p_runner_id, v_job.id, 'job_lease_renewed',
		jsonb_build_object('lease_expires_at', v_job.lease_expires_at), null
	);
	return public.qorpera_runner_job_json(v_job);
end
$$;

create function public.qorpera_complete_runner_job(
	p_runner_id uuid,
	p_session_token_sha256 text,
	p_job_id uuid,
	p_lease_token_sha256 text,
	p_result jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
	v_job public.qorpera_runner_jobs%rowtype;
begin
	if auth.role() <> 'service_role'
		or jsonb_typeof(p_result) <> 'object' or pg_column_size(p_result) > 65536
		or not public.qorpera_runner_session_valid(p_runner_id, p_session_token_sha256) then
		raise exception 'runner job completion is invalid' using errcode = '42501';
	end if;
	select job.* into v_job from public.qorpera_runner_jobs as job
	where job.id = p_job_id and job.runner_id = p_runner_id for update;
	if found and v_job.status = 'completed'
		and v_job.terminal_lease_token_sha256 = p_lease_token_sha256 and v_job.result = p_result then
		return public.qorpera_runner_job_json(v_job);
	end if;
	if not found or v_job.status <> 'leased' or v_job.lease_token_sha256 <> p_lease_token_sha256
		or v_job.lease_expires_at <= statement_timestamp() then
		raise exception 'runner job lease is unavailable' using errcode = '40001';
	end if;
	update public.qorpera_runner_jobs
	set status = 'completed', terminal_lease_token_sha256 = lease_token_sha256,
		lease_token_sha256 = null, lease_expires_at = null,
		result = p_result, last_error = null, finished_at = statement_timestamp()
	where id = p_job_id returning * into v_job;
	perform public.qorpera_append_runner_audit(
		v_job.profile_id, p_runner_id, v_job.id, 'job_completed',
		jsonb_build_object('attempt_count', v_job.attempt_count), null
	);
	return public.qorpera_runner_job_json(v_job);
end
$$;

create function public.qorpera_fail_runner_job(
	p_runner_id uuid,
	p_session_token_sha256 text,
	p_job_id uuid,
	p_lease_token_sha256 text,
	p_error text,
	p_retryable boolean
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
	v_job public.qorpera_runner_jobs%rowtype;
	v_error text := left(coalesce(nullif(btrim(p_error), ''), 'Runner job failed'), 1000);
begin
	if auth.role() <> 'service_role' or p_retryable is null
		or not public.qorpera_runner_session_valid(p_runner_id, p_session_token_sha256) then
		raise exception 'runner job failure is invalid' using errcode = '42501';
	end if;
	select job.* into v_job from public.qorpera_runner_jobs as job
	where job.id = p_job_id for update;
	if found and v_job.terminal_lease_token_sha256 = p_lease_token_sha256
		and v_job.last_error = v_error and v_job.status in ('queued', 'leased', 'failed') then
		return public.qorpera_runner_job_json(v_job);
	end if;
	if not found or v_job.status <> 'leased' or v_job.runner_id <> p_runner_id
		or v_job.lease_token_sha256 <> p_lease_token_sha256
		or v_job.lease_expires_at <= statement_timestamp() then
		raise exception 'runner job lease is unavailable' using errcode = '40001';
	end if;
	if p_retryable and v_job.attempt_count < 8 then
		update public.qorpera_runner_jobs
		set status = 'queued', runner_id = null, client_lease_id = null,
			terminal_lease_token_sha256 = lease_token_sha256,
			lease_token_sha256 = null, lease_expires_at = null, last_error = v_error
		where id = p_job_id returning * into v_job;
		perform public.qorpera_append_runner_audit(
			v_job.profile_id, p_runner_id, v_job.id, 'job_requeued',
			jsonb_build_object('attempt_count', v_job.attempt_count, 'reason', 'runner_retryable_failure'), null
		);
	else
		update public.qorpera_runner_jobs
		set status = 'failed', terminal_lease_token_sha256 = lease_token_sha256,
			lease_token_sha256 = null, lease_expires_at = null,
			last_error = v_error, finished_at = statement_timestamp()
		where id = p_job_id returning * into v_job;
		perform public.qorpera_append_runner_audit(
			v_job.profile_id, p_runner_id, v_job.id, 'job_failed',
			jsonb_build_object('attempt_count', v_job.attempt_count), null
		);
	end if;
	return public.qorpera_runner_job_json(v_job);
end
$$;

revoke all on function public.qorpera_create_runner_registration(uuid, uuid, text, jsonb, integer, text) from public;
revoke all on function public.qorpera_reissue_runner_activation(uuid, text) from public;
revoke all on function public.qorpera_list_runners(uuid) from public;
revoke all on function public.qorpera_revoke_runner(uuid) from public;
revoke all on function public.qorpera_enqueue_runner_job(uuid, uuid, uuid, uuid, text, text, jsonb) from public;
revoke all on function public.qorpera_list_runner_jobs(uuid, integer) from public;
revoke all on function public.qorpera_cancel_runner_job(uuid) from public;
revoke all on function public.qorpera_list_runner_audit(uuid, bigint, integer) from public;
revoke all on function public.qorpera_activate_runner(uuid, text, text, text, text) from public;
revoke all on function public.qorpera_heartbeat_runner(uuid, text, text, uuid) from public;
revoke all on function public.qorpera_claim_runner_job(uuid, text, uuid, text) from public;
revoke all on function public.qorpera_renew_runner_job(uuid, text, uuid, text) from public;
revoke all on function public.qorpera_complete_runner_job(uuid, text, uuid, text, jsonb) from public;
revoke all on function public.qorpera_fail_runner_job(uuid, text, uuid, text, text, boolean) from public;

grant execute on function public.qorpera_create_runner_registration(uuid, uuid, text, jsonb, integer, text) to authenticated;
grant execute on function public.qorpera_reissue_runner_activation(uuid, text) to authenticated;
grant execute on function public.qorpera_list_runners(uuid) to authenticated;
grant execute on function public.qorpera_revoke_runner(uuid) to authenticated;
grant execute on function public.qorpera_enqueue_runner_job(uuid, uuid, uuid, uuid, text, text, jsonb) to authenticated;
grant execute on function public.qorpera_list_runner_jobs(uuid, integer) to authenticated;
grant execute on function public.qorpera_cancel_runner_job(uuid) to authenticated;
grant execute on function public.qorpera_list_runner_audit(uuid, bigint, integer) to authenticated;

grant execute on function public.qorpera_activate_runner(uuid, text, text, text, text) to service_role;
grant execute on function public.qorpera_heartbeat_runner(uuid, text, text, uuid) to service_role;
grant execute on function public.qorpera_claim_runner_job(uuid, text, uuid, text) to service_role;
grant execute on function public.qorpera_renew_runner_job(uuid, text, uuid, text) to service_role;
grant execute on function public.qorpera_complete_runner_job(uuid, text, uuid, text, jsonb) to service_role;
grant execute on function public.qorpera_fail_runner_job(uuid, text, uuid, text, text, boolean) to service_role;
